definition.script:
pipeline {
  agent any

  tools {
    nodejs 'node25'
  }

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15', artifactNumToKeepStr: '5'))
    timeout(time: 150, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  environment {
    NEXUS_REGISTRY = 'localhost:5001'
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/metabuilder.git'
      }
    }

    stage('Install') {
      options { timeout(time: 25, unit: 'MINUTES') }
      steps {
        sh '''
          npm config set @esbuild-kit:registry https://registry.npmjs.org/ --location=project
          npm install --no-audit --no-fund
        '''
      }
    }

    stage('Validate') {
      options { timeout(time: 25, unit: 'MINUTES') }
      steps {
        sh '''
          npm run lint --if-present
          npm run typecheck --if-present
          npm test --if-present
          npm run build --if-present
        '''
      }
    }

    stage('Docker Preflight') {
      options { timeout(time: 10, unit: 'MINUTES') }
      steps {
        withCredentials([usernamePassword(credentialsId: 'nexus-admin', usernameVariable: 'NEXUS_ADMIN_USER', passwordVariable: 'NEXUS_ADMIN_PASSWORD')]) {
          sh '''
          docker version
          docker compose version
          curl -fsS -I http://localhost:5001/v2/ || true
          printf '%s' "$NEXUS_ADMIN_PASSWORD" | docker login "$NEXUS_REGISTRY" -u "$NEXUS_ADMIN_USER" --password-stdin
        '''
        }
      }
    }

    stage('Prune Old MetaBuilder Images') {
      steps {
        sh '''
          docker images --format '{{.Repository}}:{{.Tag}}' \
            | grep -E '^(metabuilder/|deployment-|localhost:5001/johndoe6345789/metabuilder/)' \
            | xargs -r docker rmi -f || true
          docker builder prune -af --filter until=24h || true
        '''
      }
    }

    // Base images, built as the verified dependency DAG. The three roots are
    // independent (FROM ubuntu / node:24 / python:3.14-slim) so they run in
    // parallel. android-sdk and conan-deps derive FROM base-apt, so they run
    // after the roots. conan-deps is a single 32GB image and is the host's
    // disk wall: it (and the apps that need it) is best-effort — a failure
    // marks the build UNSTABLE, never FAILURE, so the disk-safe set still ships.
    stage('Build Base Images (DAG)') {
      options { timeout(time: 90, unit: 'MINUTES') }
      steps {
        script {
          parallel(
            'apt': {
              stage('base: apt') {
                sh '''
                  set -e
                  cd deployment
                  python3 deployment.py build base apt
                '''
              }
            },
            'node-deps': {
              stage('base: node-deps') {
                sh '''
                  set -e
                  cd deployment
                  python3 deployment.py build base node-deps
                '''
              }
            },
            'pip-deps': {
              stage('base: pip-deps') {
                sh '''
                  set -e
                  cd deployment
                  python3 deployment.py build base pip-deps
                '''
              }
            }
          )
          stage('base: android-sdk') {
            catchError(message: 'android-sdk base failed', buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
              sh '''
                set -e
                cd deployment
                python3 deployment.py build base android-sdk
              '''
            }
          }
          stage('base: conan-deps (disk-gated)') {
            catchError(message: 'conan-deps (32GB) did not fit — dependent C++ apps will be skipped', buildResult: 'UNSTABLE', stageResult: 'NOT_BUILT') {
              sh '''
                set -e
                cd deployment
                python3 deployment.py build base conan-deps
              '''
            }
          }
        }
      }
    }

    // App images, one stage per image generated from the same manifest the
    // build uses (commands.json). Kept SEQUENTIAL on purpose: this host is
    // disk-constrained and 15 concurrent image builds would blow peak disk —
    // the very problem the housekeeping job exists to manage. Each app is
    // fault-tolerant: a failure (typically a disk-gated base like conan-deps)
    // marks the build UNSTABLE and the stage skipped, instead of aborting the
    // whole run, so every disk-safe image still reaches the push stage.
    stage('Build App Images (per-image)') {
      options { timeout(time: 120, unit: 'MINUTES') }
      steps {
        script {
          def defs = readJSON file: 'deployment/cli/commands.json'
          for (entry in defs.definitions.nexus_images.apps) {
            def svc = entry.name
            stage("app: ${svc}") {
              catchError(message: "app ${svc} build failed (likely a disk-gated base, e.g. conan-deps)", buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
                sh """
                  set -e
                  cd deployment
                  python3 deployment.py build apps ${svc}
                  docker builder prune -f --filter until=24h || true
                """
              }
            }
          }
        }
      }
    }

    stage('Push Images To Nexus') {
      options { timeout(time: 45, unit: 'MINUTES') }
      steps {
        withCredentials([usernamePassword(credentialsId: 'nexus-admin', usernameVariable: 'NEXUS_ADMIN_USER', passwordVariable: 'NEXUS_ADMIN_PASSWORD')]) {
          sh '''
          tag="$(git rev-parse --short HEAD)"
          slug="johndoe6345789/metabuilder"

          python3 - <<'PY'
import json
import os
import subprocess
import sys

with open("deployment/cli/commands.json") as f:
    defs = json.load(f)["definitions"]["nexus_images"]

registry = os.environ.get("NEXUS_REGISTRY", "localhost:5001")
nexus_url = os.environ.get("NEXUS_BASE_URL", "http://nexus:8081")
nexus_user = os.environ.get("NEXUS_ADMIN_USER", "admin")
nexus_password = os.environ["NEXUS_ADMIN_PASSWORD"]
tag = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], text=True).strip()
slug = "johndoe6345789/metabuilder"
images = defs["base"] + defs["apps"]

def delete_existing_component(name, version):
    import base64
    import urllib.parse
    import urllib.request

    query = urllib.parse.urlencode({
        "repository": "docker-hosted",
        "name": f"{slug}/{name}",
        "version": version,
    })
    auth = base64.b64encode(f"{nexus_user}:{nexus_password}".encode()).decode()
    req = urllib.request.Request(
        f"{nexus_url}/service/rest/v1/search?{query}",
        headers={"Authorization": f"Basic {auth}"},
    )
    with urllib.request.urlopen(req, timeout=30) as response:
        payload = json.load(response)

    for item in payload.get("items", []):
        if item.get("name") != f"{slug}/{name}" or item.get("version") != version:
            continue
        delete_req = urllib.request.Request(
            f"{nexus_url}/service/rest/v1/components/{item['id']}",
            method="DELETE",
            headers={"Authorization": f"Basic {auth}"},
        )
        with urllib.request.urlopen(delete_req, timeout=30):
            pass
        print(f"Deleted old Nexus component {slug}/{name}:{version}")

pushed = 0
missing = []
for image in images:
    local = image["local"]
    name = image["name"]
    if subprocess.run(["docker", "image", "inspect", local], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode != 0:
        missing.append(local)
        continue

    targets = [
        f"{registry}/{slug}/{name}:{tag}",
        f"{registry}/{slug}/{name}:latest",
    ]
    for target in targets:
        version = target.rsplit(":", 1)[1]
        delete_existing_component(name, version)
        subprocess.check_call(["docker", "tag", local, target])
        subprocess.check_call(["docker", "push", target])
        subprocess.run(["docker", "rmi", "-f", target], check=False)
        pushed += 1

    subprocess.run(["docker", "rmi", "-f", local], check=False)
    subprocess.run(["docker", "builder", "prune", "-af", "--filter", "until=24h"], check=False)

print(f"Pushed {pushed} image tags to {registry}/{slug}")
if missing:
    print("Skipped images that were not built:", file=sys.stderr)
    for local in missing:
        print(f"  - {local}", file=sys.stderr)
PY
        '''
        }
      }
    }
  }

  post {
    always {
      cleanWs()
    }
  }
}
